class Interpolation: 
    def __init__(self):
        pass

    @staticmethod
    def interpolate_1d(x, y, x_interp):
        """
        Linear interpolation of one-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :return: The y-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_1d([1, 2, 3], [1, 2, 3], [1.5, 2.5])
        [1.5, 2.5]

        """
        if len(x) < 2:
            raise ValueError("x must contain at least 2 entries")

        y_interp = []
        n_x = len(x)

        for xi in x_interp:
            # Find the index i such that x[i] <= xi <= x[i+1] or extrapolate
            i = 0
            while i < n_x - 1 and x[i + 1] < xi:
                i += 1

            if i == n_x - 1:
                # Extrapolate forward using the last interval
                denom = x[n_x - 1] - x[n_x - 2]
                if denom != 0:
                    t = (xi - x[n_x - 2]) / denom
                    yi = y[n_x - 2] + t * (y[n_x - 1] - y[n_x - 2])
                else:
                    yi = y[n_x - 2]
            else:
                # Normal interpolation within the bounds
                denom = x[i + 1] - x[i]
                if denom != 0:
                    t = (xi - x[i]) / denom
                    yi = y[i] + t * (y[i + 1] - y[i])
                else:
                    yi = y[i]

            y_interp.append(yi)

        return y_interp

